import { NextFunction, Request, Response } from 'express';
import { ErrorKind, classifyError } from '../application/ErrorClassification';

const STATUS_BY_KIND: Record<ErrorKind, number> = {
  invalid: 400,
  'not-found': 404,
  conflict: 409,
  unexpected: 500,
};

export function notFoundMiddleware(req: Request, res: Response): void {
  res.status(404).json({ error: `No route for ${req.method} ${req.path}` });
}

export function errorMiddleware(error: unknown, _req: Request, res: Response, _next: NextFunction): void {
  if (isMalformedJson(error)) {
    res.status(400).json({ error: 'Request body is not valid JSON' });
    return;
  }
  const classified = classifyError(error);
  if (classified.kind === 'unexpected') {
    console.error(error);
  }
  res.status(STATUS_BY_KIND[classified.kind]).json({ error: classified.message });
}

function isMalformedJson(error: unknown): boolean {
  return typeof error === 'object' && error !== null && (error as { type?: unknown }).type === 'entity.parse.failed';
}

