import express, { Express } from 'express';
import { errorMiddleware, notFoundMiddleware } from './ErrorMiddleware';
import { OrderController } from './OrderController';
import { ProductController } from './ProductController';

export function createHttpApp(orders: OrderController, products: ProductController): Express {
  const app = express();
  app.use(express.json());
  app.use('/orders', orders.routes());
  app.use('/products', products.routes());
  app.use(notFoundMiddleware);
  app.use(errorMiddleware);
  return app;
}

