import { Request, Response, Router } from 'express';
import { AdvanceOrderUseCase } from '../application/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { GetOrderUseCase } from '../application/GetOrderUseCase';
import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
import { PlaceOrderCommand } from '../application/OrderDto';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { asRecord, requireArray, requireNumber, requireQueryString, requireString } from './RequestParsing';

export interface OrderUseCases {
  placeOrder: PlaceOrderUseCase;
  getOrder: GetOrderUseCase;
  listOrdersByState: ListOrdersByStateUseCase;
  advanceOrder: AdvanceOrderUseCase;
  cancelOrder: CancelOrderUseCase;
}

interface OrderParams {
  id: string;
}

export class OrderController {
  constructor(private readonly useCases: OrderUseCases) {}

  routes(): Router {
    const router = Router();
    router.post('/', this.place);
    router.get('/', this.listByState);
    router.get('/:id', this.get);
    router.post('/:id/status', this.advance);
    router.post('/:id/cancel', this.cancel);
    return router;
  }

  private readonly place = (req: Request, res: Response): void => {
    res.status(201).json(this.useCases.placeOrder.execute(parsePlaceOrder(req.body)));
  };

  private readonly listByState = (req: Request, res: Response): void => {
    const state = requireQueryString(req.query['state'], 'state');
    res.json(this.useCases.listOrdersByState.execute(state));
  };

  private readonly get = (req: Request<OrderParams>, res: Response): void => {
    res.json(this.useCases.getOrder.execute(req.params.id));
  };

  private readonly advance = (req: Request<OrderParams>, res: Response): void => {
    const status = requireString(asRecord(req.body, 'Request body'), 'status');
    res.json(this.useCases.advanceOrder.execute(req.params.id, status));
  };

  private readonly cancel = (req: Request<OrderParams>, res: Response): void => {
    res.json(this.useCases.cancelOrder.execute(req.params.id));
  };
}

function parsePlaceOrder(body: unknown): PlaceOrderCommand {
  const record = asRecord(body, 'Request body');
  return {
    customerId: requireString(record, 'customerId'),
    lines: requireArray(record, 'lines').map((raw) => {
      const line = asRecord(raw, 'Order line');
      return { productId: requireString(line, 'productId'), quantity: requireNumber(line, 'quantity') };
    }),
  };
}

