import { AdvanceOrderUseCase } from '../application/AdvanceOrderUseCase';
import { CancelOrderUseCase } from '../application/CancelOrderUseCase';
import { Clock } from '../application/Clock';
import { EntityLookupService } from '../application/EntityLookupService';
import { GetOrderUseCase } from '../application/GetOrderUseCase';
import { IdGenerator } from '../application/IdGenerator';
import { ListOrdersByStateUseCase } from '../application/ListOrdersByStateUseCase';
import { PlaceOrderUseCase } from '../application/PlaceOrderUseCase';
import { OrderController } from './OrderController';
import { Persistence } from './Persistence';

/** Wires the order use cases to their adapters. */
export function createOrderController(persistence: Persistence, ids: IdGenerator, clock: Clock): OrderController {
  const { orders, products } = persistence;
  const lookup = new EntityLookupService(orders, products);
  return new OrderController({
    placeOrder: new PlaceOrderUseCase(orders, products, lookup, ids, clock),
    getOrder: new GetOrderUseCase(lookup),
    listOrdersByState: new ListOrdersByStateUseCase(orders),
    advanceOrder: new AdvanceOrderUseCase(orders, products, lookup, clock),
    cancelOrder: new CancelOrderUseCase(orders, products, lookup, clock),
  });
}

