import { Request, Response, Router } from 'express';
import { ListProductStockUseCase } from '../application/ListProductStockUseCase';
import { RegisterProductUseCase } from '../application/RegisterProductUseCase';
import { asRecord, requireNumber, requireString } from './RequestParsing';

export interface ProductUseCases {
  registerProduct: RegisterProductUseCase;
  listProductStock: ListProductStockUseCase;
}

export class ProductController {
  constructor(private readonly useCases: ProductUseCases) {}

  routes(): Router {
    const router = Router();
    router.post('/', this.register);
    router.get('/', this.listStock);
    return router;
  }

  private readonly register = (req: Request, res: Response): void => {
    const record = asRecord(req.body, 'Request body');
    const product = this.useCases.registerProduct.execute({
      productId: requireString(record, 'productId'),
      name: requireString(record, 'name'),
      initialStock: requireNumber(record, 'initialStock'),
    });
    res.status(201).json(product);
  };

  private readonly listStock = (_req: Request, res: Response): void => {
    res.json(this.useCases.listProductStock.execute());
  };
}

