import { ValidationError } from '../application/ApplicationErrors';

/** Shape checks for untrusted JSON bodies; business rules stay in the domain. */

export function asRecord(value: unknown, label: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new ValidationError(`${label} must be a JSON object`);
  }
  return value as Record<string, unknown>;
}

export function requireString(source: Record<string, unknown>, field: string): string {
  const value = source[field];
  if (typeof value !== 'string') {
    throw new ValidationError(`'${field}' must be a string`);
  }
  return value;
}

export function requireNumber(source: Record<string, unknown>, field: string): number {
  const value = source[field];
  if (typeof value !== 'number') {
    throw new ValidationError(`'${field}' must be a number`);
  }
  return value;
}

export function requireArray(source: Record<string, unknown>, field: string): unknown[] {
  const value = source[field];
  if (!Array.isArray(value)) {
    throw new ValidationError(`'${field}' must be an array`);
  }
  return value;
}

export function requireQueryString(value: unknown, name: string): string {
  if (typeof value !== 'string' || value === '') {
    throw new ValidationError(`Query parameter '${name}' is required`);
  }
  return value;
}

